package shop.ultimatesmp.weather;
import com.zaxxer.hikari.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
import org.bukkit.*;import org.bukkit.event.*;import org.bukkit.event.weather.*;import org.bukkit.event.world.TimeSkipEvent;import org.bukkit.plugin.java.JavaPlugin;
public final class UltimateWeatherTime extends JavaPlugin implements Listener {
 private final Map<String,World> worlds=new LinkedHashMap<>();private final Map<String,WorldStore.Change> edits=new LinkedHashMap<>();private final List<Long> acknowledged=new ArrayList<>();
 private final Map<String,Long> pendingUntil=new HashMap<>();
 private final AtomicBoolean busy=new AtomicBoolean();private final ExecutorService io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"UltimateWeatherTime-DB");t.setDaemon(true);return t;});
 private volatile boolean stopping;private boolean applying,leader,relay;private String id,master,url,user,password;private HikariDataSource pool;private WorldStore store;private long lastWarning;
 @Override public void onEnable(){saveDefaultConfig();JavaPlugin net=(JavaPlugin)Bukkit.getPluginManager().getPlugin("BlinkNetwork");id=net.getConfig().getString("server-id","");master=getConfig().getString("source-server","").trim();if(master.isEmpty())master=net.getConfig().getString("bootstrap-server","");
  url=env("BLINK_NETWORK_JDBC_URL",net,"database.jdbc-url").replaceFirst("^jdbc:mysql:","jdbc:mariadb:");user=env("BLINK_NETWORK_DB_USER",net,"database.username");password=env("BLINK_NETWORK_DB_PASSWORD",net,"database.password");
  if(id.isBlank()||master.isBlank()||!url.startsWith("jdbc:mariadb:")||net.getConfig().getString("role","world").equalsIgnoreCase("queue")){getLogger().severe("Requires a configured BlinkNetwork world backend using the shared Gravel MySQL/MariaDB database.");Bukkit.getPluginManager().disablePlugin(this);return;}
  leader=id.equals(master);relay=getConfig().getBoolean("relay-explicit-changes",true);for(String dim:List.of("Overworld","Nether","End")){String fallback=dim.equals("Overworld")?"world":dim.equals("Nether")?"world_nether":"world_the_end";World w=Bukkit.getWorld(net.getConfig().getString("worlds."+dim,fallback));if(w!=null)worlds.put(dim,w);}
  Bukkit.getPluginManager().registerEvents(this,this);int interval=Math.max(20,Math.min(200,getConfig().getInt("interval-ticks",40)));Bukkit.getScheduler().runTaskTimer(this,this::tick,20,interval);getLogger().info("Time/weather source: "+master+"; this backend is "+(leader?"source":"follower")+". World dimensions stay separate.");
 }
 private static String env(String key,JavaPlugin p,String path){String value=System.getenv(key);return value==null||value.isBlank()?p.getConfig().getString(path,""):value;}
 private Snapshot capture(String dim,World w){return new Snapshot(dim,w.getFullTime(),Boolean.TRUE.equals(w.getGameRuleValue(GameRule.DO_DAYLIGHT_CYCLE)),Boolean.TRUE.equals(w.getGameRuleValue(GameRule.DO_WEATHER_CYCLE)),w.hasStorm(),w.isThundering(),Math.max(0,w.getWeatherDuration()),Math.max(0,w.getThunderDuration()),Math.max(0,w.getClearWeatherDuration()),0);}
 private void tick(){if(stopping||!busy.compareAndSet(false,true))return;List<Snapshot> snapshots=worlds.entrySet().stream().map(e->capture(e.getKey(),e.getValue())).toList();List<WorldStore.Change> changes=List.copyOf(edits.values());edits.clear();List<Long> done=List.copyOf(acknowledged);
  io.execute(()->{try{
   if(store==null){HikariConfig c=new HikariConfig();c.setPoolName("UltimateWeatherTime");c.setJdbcUrl(url);c.setUsername(user);c.setPassword(password);c.setDriverClassName(org.mariadb.jdbc.Driver.class.getName());c.setMaximumPoolSize(1);c.setMinimumIdle(0);c.setConnectionTimeout(3000);c.setValidationTimeout(2000);c.addDataSourceProperty("connectTimeout","3000");c.addDataSourceProperty("socketTimeout","5000");c.setInitializationFailTimeout(-1);pool=new HikariDataSource(c);WorldStore candidate=new WorldStore(pool);try{candidate.initialize();store=candidate;}catch(Exception ex){pool.close();pool=null;throw ex;}}
   WorldStore.Batch result=store.exchange(id,master,leader,snapshots,changes,done);
   onMain(()->{acknowledged.removeAll(done);try{if(leader){for(var intent:result.requests()){apply(intent.state(),intent.kind());acknowledged.add(intent.id());}}else for(Snapshot state:result.snapshots())if(state.fresh())apply(state,"all");}finally{busy.set(false);}});
  }catch(Exception ex){if(System.currentTimeMillis()-lastWarning>30000){lastWarning=System.currentTimeMillis();getLogger().warning("World sync unavailable ("+ex.getClass().getSimpleName()+"); worlds continue normally and sync will retry.");}onMain(()->{for(var change:changes)edits.putIfAbsent(change.state().dimension()+":"+change.kind(),change);busy.set(false);});}});
 }
 private void onMain(Runnable task){if(!stopping&&isEnabled())Bukkit.getScheduler().runTask(this,()->{if(!stopping)task.run();});}
 private void apply(Snapshot s,String kind){World w=worlds.get(s.dimension());if(w==null)return;applying=true;try{
  if(!kind.equals("weather")&&(!kind.equals("all")||pendingUntil.getOrDefault(s.dimension()+":time",0L)<System.currentTimeMillis())){if(kind.equals("all"))w.setGameRule(GameRule.DO_DAYLIGHT_CYCLE,s.daylight());long time=s.predictedTime();if(Math.abs(w.getFullTime()-time)>=4)w.setFullTime(time);}
  if(!kind.equals("time")&&(!kind.equals("all")||pendingUntil.getOrDefault(s.dimension()+":weather",0L)<System.currentTimeMillis())){if(kind.equals("all"))w.setGameRule(GameRule.DO_WEATHER_CYCLE,s.weatherCycle());if(w.hasStorm()!=s.storm())w.setStorm(s.storm());if(w.isThundering()!=s.thunder())w.setThundering(s.thunder());w.setWeatherDuration(s.remaining(s.rainTicks()));w.setThunderDuration(s.remaining(s.thunderTicks()));w.setClearWeatherDuration(s.remaining(s.clearTicks()));}
 }finally{applying=false;}}
 private void changed(World w,String kind){if(applying||leader||!relay||stopping)return;worlds.entrySet().stream().filter(e->e.getValue().equals(w)).findFirst().ifPresent(e->Bukkit.getScheduler().runTask(this,()->{if(!stopping){pendingUntil.put(e.getKey()+":"+kind,System.currentTimeMillis()+8000);edits.put(e.getKey()+":"+kind,new WorldStore.Change(kind,capture(e.getKey(),w)));}}));}
 private static boolean explicit(WeatherEvent e){try{String cause=""+e.getClass().getMethod("getCause").invoke(e);return Set.of("COMMAND","PLUGIN","SLEEP").contains(cause);}catch(ReflectiveOperationException ex){return false;}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void time(TimeSkipEvent e){changed(e.getWorld(),"time");}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void weather(WeatherChangeEvent e){if(explicit(e))changed(e.getWorld(),"weather");}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void thunder(ThunderChangeEvent e){if(explicit(e))changed(e.getWorld(),"weather");}
 @Override public void onDisable(){stopping=true;Bukkit.getScheduler().cancelTasks(this);io.shutdown();try{io.awaitTermination(2,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}if(pool!=null)pool.close();io.shutdownNow();edits.clear();acknowledged.clear();}
}
